insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"Food provides energy for everything our bodies do — running, reading, and even sleeping, when we still need energy to breathe and keep our heart beating. The **energy value** of a food is the amount of energy a certain quantity of it provides. It is shown on **nutrition labels** in **kilocalories (kcal)** or **kilojoules (kJ)**. For example, a snack labelled 100 kcal provides 100 × 4.2 = 420 kJ, because 1 kcal = 4.2 kJ."}$j$),
('prose'::block_kind, null, 2, $j${"md":"Living things do not burn their food. Instead, food is broken down gradually inside cells by **respiration**. During respiration, some of the chemical energy stored in food (**glucose**) is converted into other useful forms of energy for body activities. **Oxygen** is usually needed, and **carbon dioxide** and **water** are usually produced. Respiration is a series of controlled chemical reactions, so energy is released a little at a time rather than in one hot burst."}$j$),
('prose'::block_kind, null, 3, $j${"md":"The process is summarised by two equations. The word equation is: food (glucose) + oxygen → carbon dioxide + water. The chemical equation is: C6H12O6 + 6 O2 → 6 CO2 + 6 H2O. Energy is released in the process. Compare this with photosynthesis, which stores energy in food: respiration does the opposite and releases that energy again."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Feature | Photosynthesis | Respiration |\n| --- | --- | --- |\n| Reactants | Carbon dioxide and water | Glucose and oxygen |\n| Products | Glucose and oxygen | Carbon dioxide and water |\n| Energy change | Light energy to chemical energy in food | Chemical energy in food to other useful energy |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: respiration is not breathing. Breathing only moves air in and out of the body, while respiration is the chemical reaction inside every living cell, plant or animal."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"A 50 g serving of food has an energy value of 300 kcal. Using 1 kcal = 4.2 kJ, what is its energy value in kJ?","options":[{"text":"71 kJ"},{"text":"300 kJ"},{"text":"1 260 kJ"},{"text":"630 kJ"}],"answer":2,"why":"Multiply the energy in kcal by 4.2, so 300 × 4.2 = 1 260 kJ.","wrongWhy":"Dividing by 4.2 instead of multiplying gives 71 kJ. Answer: 1 260 kJ."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"Why does respiration release the energy in food gradually, with no flame?","options":[{"text":"Because respiration is a series of controlled chemical reactions inside cells."},{"text":"Because respiration does not really release any energy."},{"text":"Because respiration only happens when food is burnt."},{"text":"Because respiration uses light energy from the Sun."}],"answer":0,"why":"Glucose is broken down step by step by controlled reactions in cells, so energy comes out slowly.","wrongWhy":"Burning releases all the energy at once with a flame, but respiration is controlled inside cells. Answer: it is a series of controlled chemical reactions inside cells."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"Which word equation summarises respiration?","options":[{"text":"carbon dioxide + water → glucose + oxygen"},{"text":"glucose + oxygen → carbon dioxide + water"},{"text":"glucose + carbon dioxide → oxygen + water"},{"text":"glucose → carbon dioxide + water + oxygen"}],"answer":1,"why":"Respiration takes in glucose and oxygen and gives out carbon dioxide and water.","wrongWhy":"The first option is the photosynthesis equation with reactants and products swapped. Answer: glucose + oxygen → carbon dioxide + water."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"In which cells does respiration take place?","options":[{"text":"Only in animal cells"},{"text":"Only in plant cells"},{"text":"Only in cells that receive light"},{"text":"In both plant cells and animal cells"}],"answer":3,"why":"Every living cell needs energy, so both plant and animal cells respire.","wrongWhy":"Light is needed for photosynthesis, not respiration, which happens in all living cells. Answer: in both plant cells and animal cells."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$energy-from-food-7-3$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$gas-exchange-in-plants-7-4$j$, $j$Gas Exchange in Plants$j$, '', 4,
            array[$j$gas-exchange-in-plants-7-4$j$], 'published', 4)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"Green plants make their own food by **photosynthesis**, which uses carbon dioxide and releases oxygen. They also **respire** all the time, using oxygen and releasing carbon dioxide. The gases you can detect around a leaf depend on which process is faster, so the **net gas exchange** is not fixed: it changes with light."}$j$),
('prose'::block_kind, null, 2, $j${"md":"In bright light both processes run, but photosynthesis is faster. The leaf therefore uses more carbon dioxide than it produces and releases more oxygen than it uses. You see a **net uptake of carbon dioxide** and a **net release of oxygen**. For example, a leaf in hydrogencarbonate indicator turns it from red to purple, because the carbon dioxide level drops below normal."}$j$),
('prose'::block_kind, null, 3, $j${"md":"In darkness photosynthesis stops but respiration continues. The plant now takes in oxygen and gives out carbon dioxide, so there is a **net release of carbon dioxide** and a **net uptake of oxygen**. The gases move through tiny pores called **stomata** on the leaf surface. Respiration never stops, even in bright light — it is only hidden by the faster photosynthesis."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Condition | Carbon dioxide | Oxygen |\n| --- | --- | --- |\n| Bright light | Net uptake | Net release |\n| Darkness | Net release | Net uptake |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Do not write that plants respire only at night — respiration runs all the time; light just lets photosynthesis overtake it."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"A green plant is left in bright sunlight. Which row describes its net gas exchange?","options":[{"text":"Net uptake of carbon dioxide and net release of oxygen"},{"text":"Net release of carbon dioxide and net uptake of oxygen"},{"text":"Net uptake of both carbon dioxide and oxygen"},{"text":"No net exchange, because the two processes cancel out"}],"answer":0,"why":"Photosynthesis runs faster than respiration in bright light, so the plant takes in more carbon dioxide than it makes and gives out more oxygen than it uses.","wrongWhy":"Both processes run, but photosynthesis is faster, so they do not cancel out. Answer: net uptake of carbon dioxide and net release of oxygen."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"A leaf is sealed in a tube of hydrogencarbonate indicator that is red at the start. After five hours in bright light the indicator is purple. What does this show?","options":[{"text":"The leaf released carbon dioxide faster than it used it"},{"text":"The leaf used up more carbon dioxide than it released"},{"text":"The leaf stopped respiring in the light"},{"text":"The indicator changed colour because of the light itself"}],"answer":1,"why":"Purple means the carbon dioxide level has fallen below normal, so photosynthesis removed more carbon dioxide than respiration added.","wrongWhy":"Purple marks a fall in carbon dioxide, not a rise, and light alone does not change the indicator. Answer: the leaf used up more carbon dioxide than it released."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"A potted plant is sealed in a clear box overnight in the dark. What happens to the air inside the box?","options":[{"text":"Carbon dioxide falls and oxygen rises"},{"text":"Carbon dioxide rises and oxygen falls"},{"text":"Both gases stay at the same level"},{"text":"Oxygen rises because the plant stops respiring"}],"answer":1,"why":"In darkness only respiration occurs, so the plant takes in oxygen and releases carbon dioxide.","wrongWhy":"The plant does not stop respiring at night — respiration continues without photosynthesis. Answer: carbon dioxide rises and oxygen falls."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Through which leaf structure do carbon dioxide and oxygen mainly enter and leave?","options":[{"text":"Stomata"},{"text":"Guard cells"},{"text":"The epidermis"},{"text":"Chloroplasts"}],"answer":0,"why":"Stomata are the pores on the leaf surface that let carbon dioxide and oxygen move in and out.","wrongWhy":"Guard cells sit around each stoma and control its opening, but the gases pass through the pore itself. Answer: stomata."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$gas-exchange-in-plants-7-4$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$gas-exchange-in-animals-7-5$j$, $j$Gas Exchange in Animals$j$, '', 4,
            array[$j$gas-exchange-in-animals-7-5$j$], 'published', 5)
    on conflict (module_id, slug) do update
