insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"Animals take in **oxygen** from the air for **respiration** and release the **carbon dioxide** made in their cells. In humans, gas exchange happens at the **air sacs**, millions of tiny cup-shaped structures in the lungs. Air travels in through the nostrils and nasal cavity, down the trachea, then through the bronchi and bronchioles to the air sacs. Their surfaces are covered with **capillaries**, and their total area is about 80 m²."}$j$),
('prose'::block_kind, null, 2, $j${"md":"At the air sacs, oxygen in the inhaled air passes into the blood in the capillaries, and carbon dioxide passes from the blood into the air sacs to be breathed out. Air is moistened and warmed by the water and blood at the air sacs, so exhaled air holds more **water vapour** and is warmer than inhaled air. Other animals use different structures: fish use **gills**, frogs use lungs and moist skin, and salamanders use external gills and skin."}$j$),
('prose'::block_kind, null, 3, $j${"md":"Use the percentages to compare the two kinds of air. Inhaled air is about 21% oxygen and 0.04% carbon dioxide; exhaled air is about 16% oxygen and 4% carbon dioxide, while nitrogen stays at 78% in both. So exhaled air has about 100 times more carbon dioxide and roughly 5 percentage points less oxygen. Smoking lowers gas exchange efficiency: **tar** coats the air sac surfaces, carbon monoxide reduces the blood's oxygen-carrying ability, and some chemicals break down air sac walls."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Gas | Inhaled air | Exhaled air |\n| --- | --- | --- |\n| Oxygen | 21% | 16% |\n| Carbon dioxide | 0.04% | 4% |\n| Water vapour | Variable | Saturated |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exhaled air is not pure carbon dioxide — it still contains about 16% oxygen, so a candle still burns in it, just for a shorter time."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"Where does gas exchange take place in the human body?","options":[{"text":"In the bronchi"},{"text":"At the air sacs"},{"text":"In the trachea"},{"text":"In the diaphragm"}],"answer":1,"why":"The air sacs have thin, moist surfaces and are wrapped in capillaries, so gases pass between the air and the blood there.","wrongWhy":"The bronchi and trachea are only tubes that carry air, and the diaphragm only moves air in and out. Answer: at the air sacs."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"Inhaled air contains 21% oxygen and 0.04% carbon dioxide. Exhaled air contains 16% oxygen and 4% carbon dioxide. Which conclusion do these figures support?","options":[{"text":"Exhaled air contains no oxygen."},{"text":"Nitrogen makes up a smaller share of exhaled air."},{"text":"Exhaled air contains about 100 times more carbon dioxide than inhaled air."},{"text":"Breathing produces oxygen, so exhaled air is richer in oxygen."}],"answer":2,"why":"Carbon dioxide rises from 0.04% to 4%, a hundredfold increase, because respiring body cells release it.","wrongWhy":"Exhaled air still has about 16% oxygen and the same 78% nitrogen, so the oxygen has fallen rather than risen. Answer: about 100 times more carbon dioxide."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"A burning candle is lowered into a jar of inhaled air, then into a jar of exhaled air. It goes out sooner in the exhaled air. What is the best explanation?","options":[{"text":"Exhaled air is warmer, and heat melts the candle faster."},{"text":"Exhaled air contains less oxygen, and oxygen is needed for burning."},{"text":"Exhaled air contains more carbon dioxide, which is the only gas that puts out flames."},{"text":"Water vapour in exhaled air wets the wick so it cannot burn."}],"answer":1,"why":"Oxygen supports burning, and exhaled air has only about 16% oxygen against 21% in inhaled air, so the flame runs out of oxygen sooner.","wrongWhy":"Extra carbon dioxide or water vapour is not what ends the flame — the jar simply uses up its smaller oxygen supply faster. Answer: exhaled air contains less oxygen."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Tar in cigarette smoke is deposited in the lungs. How does this reduce the efficiency of gas exchange?","options":[{"text":"It covers part of the surface of the air sacs."},{"text":"It makes the air sacs expand and hold more air."},{"text":"It widens the bronchioles so air moves too fast."},{"text":"It carries oxygen away from the blood."}],"answer":0,"why":"Tar coats the surface of the air sacs, leaving less area for oxygen and carbon dioxide to pass through.","wrongWhy":"Tar blocks the exchange surface rather than widening airways, and it is carbon monoxide that reduces the blood's oxygen-carrying ability. Answer: it covers part of the air sac surface."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$gas-exchange-in-animals-7-5$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$carbon-dioxide-balance-in-nature-7-6$j$, $j$Carbon Dioxide Balance in Nature$j$, '', 4,
            array[$j$carbon-dioxide-balance-in-nature-7-6$j$], 'published', 6)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"Two processes keep the gases in air steady. In **respiration**, animals and plants take in oxygen from the air and give out carbon dioxide. In **photosynthesis**, green plants take in carbon dioxide and give out oxygen. Each gas given out by one process is used up by the other, so the amounts of oxygen and carbon dioxide in the atmosphere stay almost constant."}$j$),
('prose'::block_kind, null, 2, $j${"md":"Human activities have disrupted this balance. Since the Industrial Revolution in the late 1700s, people have burnt large amounts of **fossil fuels** in motor cars, power stations and factories, releasing a lot of carbon dioxide. Large areas of forest have also been cleared for timber and land, so less carbon dioxide is absorbed by plants for photosynthesis. For example, the carbon dioxide level was almost constant for 2000 years, but has risen sharply since the 1700s."}$j$),
('prose'::block_kind, null, 3, $j${"md":"Carbon dioxide is a **greenhouse gas**. It absorbs thermal energy given off by the Earth's surface and re-emits it, keeping the Earth warm enough for life — this is the **greenhouse effect**. Extra carbon dioxide strengthens the effect, so the Earth's average temperature rises; this is **global warming**. Scientists believe this brings **climate change**: melting polar ice, rising sea levels, more heat waves and droughts, and dying corals. **Methane**, released when cattle and sheep digest food, is another greenhouse gas."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Process | Gas taken in | Gas given out |\n| --- | --- | --- |\n| Photosynthesis in plants | Carbon dioxide | Oxygen |\n| Respiration in living things | Oxygen | Carbon dioxide |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: answer with the chain, not just the words — more carbon dioxide → stronger greenhouse effect → global warming → climate change."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"How are the levels of oxygen and carbon dioxide in the atmosphere kept almost constant?","options":[{"text":"Plants release carbon dioxide during photosynthesis and animals take it in during respiration."},{"text":"Living things take in oxygen and give out carbon dioxide in respiration, while plants take in carbon dioxide and give out oxygen in photosynthesis."},{"text":"Carbon dioxide is removed from the air only when fossil fuels are burnt."},{"text":"Oxygen and carbon dioxide stay constant because neither gas ever leaves the atmosphere."}],"answer":1,"why":"Respiration and photosynthesis use up each other's waste gas, so the two gases balance.","wrongWhy":"This swaps the two gases — plants take in carbon dioxide and give out oxygen in photosynthesis. Answer: living things take in oxygen and give out carbon dioxide, while plants do the reverse."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"A graph shows the carbon dioxide level was almost constant from year 0 to 1700, then rose sharply to its highest value by 2020. Which explanation best fits the graph?","options":[{"text":"Living things stopped carrying out respiration after 1700."},{"text":"The greenhouse effect stopped, so carbon dioxide could not escape from the atmosphere."},{"text":"Large amounts of fossil fuels were burnt and forests were cleared, so more carbon dioxide was released and less was taken up by plants."},{"text":"Plants gave out carbon dioxide instead of oxygen once the Industrial Revolution began."}],"answer":2,"why":"Burning fossil fuels adds carbon dioxide while clearing forests removes the plants that would absorb it.","wrongWhy":"The sharp rise comes from human activity, not from plants changing what they do. Answer: more fossil fuels burnt and fewer forests to absorb the carbon dioxide."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"Which statement about greenhouse gases is correct?","options":[{"text":"Greenhouse gases produce thermal energy, which warms the Earth."},{"text":"Greenhouse gases absorb thermal energy and re-emit it, keeping the Earth warmer than it would otherwise be."},{"text":"Greenhouse gases block all sunlight from reaching the Earth."},{"text":"The greenhouse effect only began after the Industrial Revolution."}],"answer":1,"why":"Greenhouse gases trap and re-emit thermal energy rather than creating it, and the effect is a natural process.","wrongWhy":"Greenhouse gases do not make thermal energy — they trap energy that is already there, and the effect is natural. Answer: they absorb and re-emit thermal energy."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Scientists say global warming may cause climate change. Which outcome is a likely consequence?","options":[{"text":"Average temperatures around the world would fall."},{"text":"Polar bears would gain more ice to live on."},{"text":"Melting ice would raise sea levels and flood low-lying areas."},{"text":"Corals would survive better because the oceans would be cooler."}],"answer":2,"why":"Warmer temperatures melt polar ice, and the extra water raises sea levels.","wrongWhy":"Global warming melts ice rather than adding to it, and the water has to go somewhere. Answer: melting ice raises sea levels and floods low-lying areas."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$carbon-dioxide-balance-in-nature-7-6$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$simple-circuits-8-1$j$, $j$Simple Circuits$j$, '', 4,
            array[$j$simple-circuits-8-1$j$], 'published', 7)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"An electrical appliance works only when two conditions are met. First, there must be a source of electrical energy, such as a cell, a battery, a generator or a solar panel. Second, the source and the appliance must form a **closed circuit** — a complete loop that leaves one end of the source, passes through the appliance and returns to the other end. A circuit with a gap is an **open circuit**, and the appliance will not work."}$j$),
('prose'::block_kind, null, 2, $j${"md":"In a closed circuit, energy changes form. Chemical energy stored in the cell is converted to electrical energy, which the circuit transfers to the bulb. The bulb then converts this electrical energy to light energy and thermal energy. A torch is a simple example: its cells, switch, wires and bulb form a closed loop, so the bulb gives out light and heat."}$j$),
('prose'::block_kind, null, 3, $j${"md":"Materials that let electricity pass through them are **electrical conductors**. Metals, **graphite** (pencil lead) and vinegar conduct electricity. Materials that block electricity are **electrical insulators** — plastics, wood, rubber and distilled water. A **switch** uses both: its conducting parts touch to close the circuit, while the insulating part we press protects us from an electric shock."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Material | Conducts? | Type |\n| --- | --- | --- |\n| Iron nail, aluminium foil | ✓ | Conductor |\n| Pencil lead (graphite) | ✓ | Conductor |\n| Vinegar, lemon juice | ✓ | Conductor |\n| Rubber band, distilled water | ✗ | Insulator |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: a bulb lights only when BOTH conditions are met — a source of electrical energy AND a closed loop. If either one is missing, the circuit is open and the bulb stays off."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"What two conditions must be met for an electrical appliance to work?","options":[{"text":"A source of electrical energy and a closed circuit"},{"text":"A switch and a bulb"},{"text":"A closed circuit only"},{"text":"A battery and an insulator"}],"answer":0,"why":"The source supplies the energy and the closed loop lets it flow through the appliance.","wrongWhy":"A switch is only a convenient way to open and close a circuit, not a requirement for energy to flow. Answer: a source of electrical energy and a closed circuit."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"In Practical 8.2, four groups of materials were tested. Which group contains only electrical conductors?","options":[{"text":"Distilled water, rubber band, wooden chopstick"},{"text":"Iron nail, pencil lead, vinegar"},{"text":"Rubber band, alcohol, plastic"},{"text":"Distilled water, vinegar, aluminium foil"}],"answer":1,"why":"Metals, graphite (pencil lead) and vinegar all let electricity pass through them.","wrongWhy":"Distilled water, rubber and wood are insulators, so any group containing them is not all conductors. Answer: iron nail, pencil lead and vinegar."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"A torch is switched on, then the switch is slid to the open position. Why does the torch go off?","options":[{"text":"The cell has used up all its chemical energy"},{"text":"The bulb has turned into an electrical insulator"},{"text":"The conducting parts of the switch no longer touch, so the circuit is open"},{"text":"The switch changes electrical energy into light energy"}],"answer":2,"why":"An open switch breaks the loop, so electrical energy can no longer be transferred to the bulb.","wrongWhy":"The cell is unchanged and the bulb is still a conductor — the break is at the switch, which makes the circuit incomplete. Answer: the conducting parts of the switch no longer touch, so the circuit is open."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"In a closed circuit containing a cell and a bulb, what is the correct order of energy changes?","options":[{"text":"Light energy → electrical energy → chemical energy"},{"text":"Electrical energy → chemical energy → light energy"},{"text":"Chemical energy → light energy → electrical energy"},{"text":"Chemical energy → electrical energy → light energy and thermal energy"}],"answer":3,"why":"The cell stores chemical energy, the circuit carries electrical energy, and the bulb gives out light and thermal energy.","wrongWhy":"The bulb does not create electrical energy, so light cannot come before it in the chain. Answer: chemical energy → electrical energy → light energy and thermal energy."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$simple-circuits-8-1$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$electric-current-8-2$j$, $j$Electric Current$j$, '', 4,
            array[$j$electric-current-8-2$j$], 'published', 8)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"In a **closed circuit**, electric charges flow round without stopping. This flow of electric charges is called an **electric current**, or current for short. The charges leave the positive terminal of the cell, pass through the appliance, and return to the negative terminal. A steady current needs two things: an energy source and a complete path."}$j$),
('prose'::block_kind, null, 2, $j${"md":"We measure current with an **ammeter**, connected in series in the circuit. Its unit is the **ampere** (A); smaller currents are measured in milliamperes (mA), where 1 mA = 0.001 A. For example, 250 mA is 250 × 0.001 = 0.25 A. The red knob (+) goes to the positive terminal of the cell and the black knob (−) to the negative terminal."}$j$),
('prose'::block_kind, null, 3, $j${"md":"A current has two useful effects. The **heating effect**: thermal energy is given out when a current flows through a conductor, so a kettle's heating part becomes hot, and the effect grows as the current grows. The **magnetic effect**: a coil of wire carrying a current becomes an **electromagnet** and attracts paper clips. Adding a cell raises the current, which makes the bulb brighter."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Water flow model | Circuit |\n| --- | --- |\n| Water pump | Cell |\n| Pipe and channel | Connecting wire |\n| Water flow | Current |\n| Turbine | Bulb |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"For a direction question, say: from the positive terminal of the cell, through the appliance, to the negative terminal. Arrows drawn the other way lose the mark."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"What is an electric current?","options":[{"text":"A flow of electric charges round a closed circuit"},{"text":"A flow of electrical energy from a cell"},{"text":"The push a cell gives to the charges in a wire"},{"text":"The number of charges stored inside a cell"}],"answer":0,"why":"Current is the flow of electric charges, which needs an energy source and a complete path.","wrongWhy":"Treating current as a flow of energy or as a push confuses it with energy transfer and with voltage. Answer: a flow of electric charges."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"A current of 250 mA flows through a bulb. What is this current in amperes?","options":[{"text":"0.025 A"},{"text":"0.25 A"},{"text":"2.5 A"},{"text":"250 000 A"}],"answer":1,"why":"1 mA = 0.001 A, so 250 mA = 250 × 0.001 A = 0.25 A.","wrongWhy":"Dividing by 10 000 gives 0.025 A, and multiplying instead of dividing gives 250 000 A; milli means thousandths. Answer: 0.25 A."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"A student adds one more cell, connected the same way, to a circuit with a single bulb. What happens?","options":[{"text":"The current increases and the bulb becomes brighter"},{"text":"The current increases but the bulb stays equally bright"},{"text":"The current stays the same because the bulb has not changed"},{"text":"The current decreases and the bulb becomes dimmer"}],"answer":0,"why":"In Practical 8.4, adding cells in the same direction increased the current and the bulb grew brighter.","wrongWhy":"Cells in the same direction add energy rather than oppose each other, so the current cannot fall or stay fixed. Answer: the current increases and the bulb becomes brighter."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"A coil of insulated copper wire is wound round an iron nail and joined to a cell. When the switch is closed, the coil","options":[{"text":"becomes an electromagnet and attracts paper clips"},{"text":"becomes a permanent magnet that still attracts after the switch is opened"},{"text":"becomes magnetic only if the wire is made of plastic"},{"text":"gets hot but shows no magnetic effect at all"}],"answer":0,"why":"A current through a coil of wire produces the magnetic effect, turning the coil into an electromagnet.","wrongWhy":"The magnetism lasts only while current flows, and the coil must be a conductor such as copper, not plastic. Answer: it becomes an electromagnet and attracts paper clips."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$electric-current-8-2$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$voltage-in-circuits-8-3$j$, $j$Voltage in Circuits$j$, '', 4,
            array[$j$voltage-in-circuits-8-3$j$], 'published', 9)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"A cell pushes electric charges around a circuit, and its **voltage** tells you how much energy it gives to those charges. The unit is the **volt** (V). You can picture voltage with the water model: a cell works like a pump, and a higher voltage is like a stronger pump that lifts water to a higher level. An AA-cell has a voltage of 1.5 V."}$j$),
('prose'::block_kind, null, 2, $j${"md":"We measure voltage with a **voltmeter**, whose circuit symbol is V inside a circle. Connect it **across** the cell or bulb, in parallel, never in the same line as the current. The red knob goes to the positive terminal and the black knob to the negative terminal, because reversing them can damage the meter. If the meter has a 5-V knob, use it for readings below 5 V to get a more precise value."}$j$),
('prose'::block_kind, null, 3, $j${"md":"Cells joined in the same direction add up: three 1.5 V cells give 1.5 + 1.5 + 1.5 = 4.5 V. If one cell is reversed, its voltage is subtracted, so 1.5 − 1.5 + 1.5 = 1.5 V. A higher voltage also makes the current larger, so a bulb glows brighter. In daily life a power bank is about 5 V, while mains electricity in Hong Kong is 220 V."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Cells connected | Overall voltage |\n| --- | --- |\n| One 1.5 V cell | 1.5 V |\n| Two 1.5 V cells, same direction | 1.5 + 1.5 = 3.0 V |\n| Two 1.5 V cells, opposite directions | 1.5 − 1.5 = 0 V |\n| Three 1.5 V cells, one reversed | 1.5 − 1.5 + 1.5 = 1.5 V |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: add the voltages of cells pointing the same way, subtract any cell that is reversed, then use the total to judge the current."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"What does the voltage of a cell tell you?","options":[{"text":"How much chemical energy the cell stores"},{"text":"How fast the electric charges move through the wires"},{"text":"How much energy the cell supplies to the electric charges in the circuit"},{"text":"How long the cell will last before it goes flat"}],"answer":2,"why":"Voltage measures the energy supplied to the charges, not the size or lifetime of the cell.","wrongWhy":"It is easy to confuse voltage with stored chemical energy or with how long a cell lasts, but two 1.5-V cells of different sizes have the same voltage. Answer: how much energy the cell supplies to the electric charges."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"A student connects a voltmeter to measure the voltage of a cell. Which connection is correct?","options":[{"text":"The voltmeter in the same line as the cell, so the current flows through it"},{"text":"Red knob to the positive terminal and black knob to the negative terminal, with the voltmeter across the cell"},{"text":"Red knob to the negative terminal and black knob to the positive terminal, with the voltmeter across the cell"},{"text":"The voltmeter across the switch, with either knob on each side"}],"answer":1,"why":"The red (+) knob must meet the positive terminal, and the meter sits across the cell in parallel.","wrongWhy":"Putting the meter in the current path or swapping the knobs is wrong and can damage it; the red knob belongs on the positive terminal. Answer: red knob to positive, black to negative, across the cell."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"A bulb is lit by one cell. A second identical cell is added in the same direction. What happens?","options":[{"text":"The voltage and the current both increase, so the bulb glows more brightly"},{"text":"The voltage increases but the current stays the same, so the brightness is unchanged"},{"text":"The current increases but the voltage stays the same, so the bulb glows more brightly"},{"text":"The voltage increases but the current decreases, so the bulb glows more dimly"}],"answer":0,"why":"Cells in the same direction add their voltages, which raises the current and brightens the bulb.","wrongWhy":"Voltage and current rise together in a simple circuit, so the brightness cannot stay the same or drop. Answer: both increase and the bulb glows more brightly."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Two 1.5 V cells are connected in opposite directions. What is the voltage across them?","options":[{"text":"1.5 V"},{"text":"3.0 V"},{"text":"0.75 V"},{"text":"0 V"}],"answer":3,"why":"A reversed cell subtracts its voltage, so 1.5 − 1.5 = 0 V.","wrongWhy":"The voltages are not added when the cells oppose each other; the reversed cell cancels the other. Answer: 0 V."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$voltage-in-circuits-8-3$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$resistance-and-resistors-8-4$j$, $j$Resistance and Resistors$j$, '', 4,
            array[$j$resistance-and-resistors-8-4$j$], 'published', 10)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"**Resistance** measures how difficult it is for a current to pass through a conductor. A good conductor, such as copper, has a low resistance, so charges flow through it easily. The unit of resistance is the **ohm** (Ω), named after the scientist Georg Ohm. In Practical 8.10, a copper wire and a nichrome wire of the same length and thickness were compared: the copper wire had the lower resistance and let a larger current flow, so the bulb was brighter."}$j$),
('prose'::block_kind, null, 2, $j${"md":"A **resistor** is a circuit component with a certain value of resistance. It has no positive or negative terminal, so its **polarity** does not matter and you can connect it either way round. If the voltage stays the same, a higher resistance gives a smaller current, because the current finds it harder to flow. That is why resistors are built into appliances to keep the current at a safe size. Worked example: in Practical 8.9, replacing a resistor with one of higher resistance made the ammeter reading fall."}$j$),
('prose'::block_kind, null, 3, $j${"md":"The resistance of a wire depends on its material, length and thickness. For wires of the same material, a longer wire or a thinner wire has a higher resistance. A **rheostat** is a variable resistor whose resistance can be adjusted. In a sliding rheostat, moving the contact so the current passes through a shorter length of resistive wire lowers the resistance, so the current rises and a bulb gets brighter. Worked example: a short, thick USB cable has a lower resistance, so it charges a phone faster."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Factor | Effect on resistance |\n| --- | --- |\n| Material | Copper wire has a lower resistance than nichrome wire of the same length and thickness |\n| Length | A longer wire has a higher resistance |\n| Thickness | A thinner wire has a higher resistance |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: when a bulb dims, follow the chain — a longer or thinner resistive wire gives a higher resistance, a smaller current and a dimmer bulb."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"Which statement about resistance is correct?","options":[{"text":"A good conductor has a high resistance."},{"text":"Resistance measures how difficult it is for current to pass through a conductor."},{"text":"Resistance is measured in volts."},{"text":"A resistor must be connected the right way round because it has polarity."}],"answer":1,"why":"Resistance measures the opposition of a material to the flow of current.","wrongWhy":"Good conductors have a low resistance, not a high one, and a resistor has no polarity. Answer: resistance measures how difficult it is for current to flow."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"Two resistors, of 5 Ω and 20 Ω, are connected in turn to the same cell. What happens to the current?","options":[{"text":"The current is larger with the 20 Ω resistor."},{"text":"The current is the same in both cases."},{"text":"The current is larger with the 5 Ω resistor."},{"text":"The current falls to zero with the 20 Ω resistor."}],"answer":2,"why":"At a fixed voltage, a higher resistance gives a smaller current.","wrongWhy":"A higher resistance makes it harder for current to flow, so the smaller resistor gives the larger current. Answer: the current is larger with the 5 Ω resistor."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"In a sliding rheostat, the contact is moved so that the current passes through a shorter length of resistive wire. What happens to the bulb in the circuit?","options":[{"text":"It becomes brighter because the resistance decreases."},{"text":"It becomes dimmer because the resistance increases."},{"text":"Its brightness does not change."},{"text":"It becomes brighter because the resistance increases."}],"answer":0,"why":"A shorter length of resistive wire means lower resistance, so a larger current flows and the bulb is brighter.","wrongWhy":"A longer wire raises resistance and dims the bulb; shortening the wire lowers it. Answer: it becomes brighter because the resistance decreases."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Four wires have the same length. Which one has the highest resistance?","options":[{"text":"A thick copper wire"},{"text":"A thin copper wire"},{"text":"A thick nichrome wire"},{"text":"A thin nichrome wire"}],"answer":3,"why":"Nichrome has a higher resistance than copper, and a thin wire has a higher resistance than a thick one.","wrongWhy":"Both the material and the thickness matter, so the worst case combines nichrome with a thin wire. Answer: a thin nichrome wire."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$resistance-and-resistors-8-4$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$series-and-parallel-circuits-8-5$j$, $j$Series and Parallel Circuits$j$, '', 5,
            array[$j$series-and-parallel-circuits-8-5$j$], 'published', 11)
    on conflict (module_id, slug) do update
      set title = excluded.title, ord = excluded.ord, status = 'published';
insert into blocks (lesson_id, kind, level, ord, payload)
    select l.id, v.kind, v.level, v.ord, v.payload::jsonb
      from lessons l
      cross join (values
('prose'::block_kind, null, 1, $j${"md":"A **series circuit** has only one path for current, so the components are connected one after another. The current is the same at every point: I1 = I2 = I3. The voltage of the cells is shared between the components, so V1 = V2 + V3. If the circuit is broken at any point, current stops and every bulb goes out."}$j$),
('prose'::block_kind, null, 2, $j${"md":"A **parallel circuit** splits current into more than one **branch**. The current in the main loop equals the sum of the currents in the branches: I3 = I1 + I2. The voltage across each branch is the same, V1 = V2 = V3. If one branch breaks, current still flows in the others, which is why one street lamp can fail while the rest stay lit."}$j$),
('prose'::block_kind, null, 3, $j${"md":"Branches do not always carry equal currents. A branch with a lower resistance gets a larger current. **Worked example:** a main loop carries 3 A and splits into two branches; if one branch takes 1 A, the other takes 3 A − 1 A = 2 A. Even so, the voltage across each branch stays the same."}$j$),
('prose'::block_kind, null, 4, $j${"md":"| Feature | Series circuit | Parallel circuit |\n| --- | --- | --- |\n| Current | Same at all points | Main loop = sum of branches |\n| Voltage | Sum across components = source | Same across every branch |\n| If broken | Current stops everywhere | Other branches still work |"}$j$),
('callout'::block_kind, null, 5, $j${"tone":"tip","md":"Exam tip: count the current paths first — one path means a series circuit, more than one means a parallel circuit."}$j$),
('mcq'::block_kind, 'recall'::item_level, 6, $j${"prompt":"Two identical bulbs are connected in series with a 3 V battery. What is true about the current through each bulb?","options":[{"text":"It is larger in the bulb nearer the battery"},{"text":"It is the same through both bulbs"},{"text":"It is zero because the bulbs share the voltage"},{"text":"It is halved in the second bulb"}],"answer":1,"why":"A series circuit has only one path, so the current is the same at all points.","wrongWhy":"Thinking current is used up as it passes through components. Answer: it is the same through both bulbs."}$j$),
('mcq'::block_kind, 'apply'::item_level, 7, $j${"prompt":"A parallel circuit is connected to a 3 V battery. The voltage across one branch is 3 V. What is the voltage across the other branch?","options":[{"text":"0 V"},{"text":"1.5 V"},{"text":"3 V"},{"text":"6 V"}],"answer":2,"why":"In a parallel circuit the voltage across every branch equals the source voltage.","wrongWhy":"Dividing the voltage between the branches as if they were in series. Answer: 3 V."}$j$),
('mcq'::block_kind, 'apply'::item_level, 8, $j${"prompt":"In a parallel circuit the main loop carries 5 A and branch PQ carries 2 A. What current flows in branch RS?","options":[{"text":"2 A"},{"text":"3 A"},{"text":"5 A"},{"text":"7 A"}],"answer":1,"why":"The main-loop current equals the sum of the branch currents, so 5 A − 2 A = 3 A.","wrongWhy":"Assuming branches always carry equal currents. Answer: 3 A."}$j$),
('mcq'::block_kind, 'apply'::item_level, 9, $j${"prompt":"Three identical bulbs are connected in parallel. Bulb X is unscrewed and removed. What happens?","options":[{"text":"All the other bulbs go out"},{"text":"The other bulbs stay lit at the same brightness"},{"text":"The other bulbs become dimmer"},{"text":"Current stops flowing in the main loop"}],"answer":1,"why":"Breaking one branch leaves the other branches complete, and their voltage is unchanged.","wrongWhy":"Treating a parallel circuit like a series one, where one break stops everything. Answer: the other bulbs stay lit at the same brightness."}$j$)
      ) as v(kind, level, ord, payload)
     where l.module_id = 'sci.f2' and l.slug = $j$series-and-parallel-circuits-8-5$j$
       and not exists (select 1 from blocks b where b.lesson_id = l.id);
insert into lessons (module_id, slug, title, summary, minutes, concepts, status, ord)
    values ('sci.f2', $j$household-electricity-8-6$j$, $j$Household Electricity$j$, '', 4,
            array[$j$household-electricity-8-6$j$], 'published', 12)
